import React, { useEffect, useState } from 'react';
import axios from 'axios';
import ReviewList from '../components/ReviewList';
import ReviewForm from '../styles/ReviewForm';

const Home = () => {
  const [reviews, setReviews] = useState([]);
  const restaurantId = 'restaurantId1'; // Change this dynamically if needed

  const fetchReviews = async () => {
    try {
      const result = await axios.get(`/api/reviews/${restaurantId}`);
      setReviews(result.data);
    } catch (error) {
      console.error('Error fetching reviews:', error);
    }
  };

  useEffect(() => {
    fetchReviews();
  }, []);

  const handleSave = () => {
    fetchReviews();
  };

  const handleDelete = async (reviewId: string) => {
    try {
      await axios.delete(`/api/reviews/${reviewId}`);
      fetchReviews();
    } catch (error) {
      console.error('Error deleting review:', error);
    }
  };

  const handleEdit = (review: any) => {
    // Implement navigation to edit page if needed
    // For example:
    // router.push(`/reviews/edit?id=${review._id}`);
    console.log('Edit review:', review);
  };

  return (
    <div>
      <h1>Customer Reviews</h1>
      <ReviewForm restaurantId={restaurantId} onSave={handleSave} />
      <ReviewList reviews={reviews} onEdit={handleEdit} onDelete={handleDelete} />
    </div>
  );
};

export default Home;
